sys_script.script:
// Auto-update well status based on operation status
var wellGr = new GlideRecord('x_1842888_drilling_well');
if (wellGr.get(current.well)) {
    var operationStatus = current.operation_status.toString();

    if (operationStatus == 'in_progress' && wellGr.well_status != 'drilling') {
        wellGr.well_status = 'drilling';
        wellGr.update();
        gs.addInfoMessage('Well status updated to Drilling');
    } else if (operationStatus == 'completed') {
        // Check if this is the last planned operation
        var opGr = new GlideRecord('x_1842888_drilling_drilling_operation');
        opGr.addQuery('well', current.well);
        opGr.addQuery('operation_status', 'planned');
        opGr.query();

        if (!opGr.hasNext() && wellGr.well_status != 'completed') {
            wellGr.well_status = 'completed';
            wellGr.completion_date = new GlideDateTime().getDisplayValue();
            wellGr.update();
            gs.addInfoMessage('Well status updated to Completed');
        }
    }
}
